snapshot.document:
query WalletSchemaSnapshot {
  checkpoint(sequenceNumber: 0) {
    sequenceNumber
    digest
    query {
      __typename
    }
  }
  serviceConfig {
    availableRange(type: "Query", field: "checkpoints", filters: []) {
      first {
        sequenceNumber
      }
      last {
        sequenceNumber
      }
    }
    defaultPageSize(type: "Address", field: "objects")
    maxPageSize(type: "Address", field: "objects")
  }
}

balances.document:
query WalletSchemaBalances($checkpoint: UInt53!, $owner: RtdAddress!, $cursor: String) {
  checkpoint(sequenceNumber: $checkpoint) {
    sequenceNumber
    digest
    query {
      address(address: $owner) {
        address
        balances(first: 50, after: $cursor) {
          pageInfo {
            hasNextPage
            endCursor
          }
          nodes {
            coinType {
              repr
            }
            totalBalance
            coinBalance
            addressBalance
          }
        }
      }
    }
  }
}

