ownedObjects.document:
query WalletSchemaObjects($checkpoint: UInt53!, $owner: RtdAddress!, $cursor: String, $filter: ObjectFilter) {
  checkpoint(sequenceNumber: $checkpoint) {
    sequenceNumber
    digest
    query {
      address(address: $owner) {
        address
        objects(first: 50, after: $cursor, filter: $filter) {
          pageInfo {
            hasNextPage
            endCursor
          }
          nodes {
            address
            version
            digest
            hasPublicTransfer
            owner {
              __typename
              ... on AddressOwner {
                address {
                  address
                }
              }
              ... on ObjectOwner {
                address {
                  address
                }
              }
              ... on Shared {
                initialSharedVersion
              }
              ... on ConsensusAddressOwner {
                startVersion
                address {
                  address
                }
              }
            }
            contents {
              bcs
              json
              type {
                repr
              }
              display {
                output
                errors
                basis {
                  __typename
                  ... on DisplayV1Basis {
                    snapshotCheckpoint
                    objectType
                    templateId
                    publishedVersion
                    sourceCheckpoint
                    sourceCheckpointDigest
                    transactionDigest
                    checkpointTransactionIndex
                    eventIndex
                    eventBcsSha256
                    historyCoverage {
                      genesisDigest
                      sourceId
                      generation
                      firstCheckpoint
                      lastCheckpoint
                      lastCheckpointDigest
                      snapshotCheckpoint
                      snapshotCheckpointDigest
                    }
                  }
                  ... on DisplayV2Basis {
                    snapshotCheckpoint
                    objectType
                    templateId
                    objectVersion
                    objectDigest
                    sourceCheckpoint
                    previousTransactionDigest
                    contentsBcsSha256
                    historyCoverage {
                      genesisDigest
                      sourceId
                      generation
                      firstCheckpoint
                      lastCheckpoint
                      lastCheckpointDigest
                      snapshotCheckpoint
                      snapshotCheckpointDigest
                    }
                  }
                }
              }
            }
            previousTransaction {
              digest
            }
          }
        }
      }
    }
  }
}

