dynamicFields.document:
query WalletSchemaDynamicFields($checkpoint: UInt53!, $parent: RtdAddress!, $cursor: String, $name: DynamicFieldName!) {
  checkpoint(sequenceNumber: $checkpoint) {
    sequenceNumber
