    query {
      address(address: $parent) {
        address
        dynamicFields(first: 50, after: $cursor) {
          pageInfo {
            hasNextPage
            endCursor
          }
          nodes {
            address
            name {
              bcs
              type {
                repr
              }
            }
            value {
              __typename
              ... on MoveValue {
                bcs
                type {
                  repr
                }
              }
              ... on MoveObject {
                address
                contents {
                  bcs
                  type {
                    repr
                  }
                }
              }
            }
